import s1Json from './generated/s1.json';
import type { Scenario } from './types';
import { parseScenario } from './validate';

/** Registered synthetic scenarios. Every entry is generated by tools/export_scenarios.py and
 *  validated at load. Add new scenarios here (UI2). */
export const SCENARIOS: readonly Scenario[] = [parseScenario(s1Json)];

export function scenarioById(id: string): Scenario | undefined {
  return SCENARIOS.find((s) => s.id === id);
}
